-- GENERATED by `python3 -m analytics render evidence` (analytics/specs/ceo_weekly_pulse.yml#new_vs_returning_orders; inputs sha256 f86822d969fa5fa3). Do not edit by hand.
SELECT
  CAST(timezone('Asia/Ho_Chi_Minh', m.ordered_at) AS DATE) AS day,
  COUNT(DISTINCT m.order_id) FILTER (WHERE CAST(timezone('Asia/Ho_Chi_Minh', j_customers.first_order_date) AS DATE) = CAST(timezone('Asia/Ho_Chi_Minh', m.ordered_at) AS DATE)) AS new_customer_orders,
  COUNT(DISTINCT m.order_id) FILTER (WHERE CAST(timezone('Asia/Ho_Chi_Minh', j_customers.first_order_date) AS DATE) IS DISTINCT FROM CAST(timezone('Asia/Ho_Chi_Minh', m.ordered_at) AS DATE)) AS returning_customer_orders
FROM main_marts.fact_orders AS m
LEFT JOIN main_marts.dim_customers AS j_customers ON m.customer_key = j_customers.customer_key
WHERE m.ordered_at >= timezone('Asia/Ho_Chi_Minh', CAST((CAST(date_trunc('week', (CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1)) AS DATE) - 7) AS TIMESTAMP))
  AND m.ordered_at < timezone('Asia/Ho_Chi_Minh', CAST(((CAST(timezone('Asia/Ho_Chi_Minh', now()) AS DATE) - 1) + 1) AS TIMESTAMP))
  AND m.scope_sales
GROUP BY 1
ORDER BY 1
